function IconButton({label,onClick,children,active=false,disabled=false}:{label:string;onClick:()=>void;children:React.ReactNode;active?:boolean;disabled?:boolean}){return <Tooltip><TooltipTrigger asChild><button className={'icon-button'+(active?' active':'')} aria-label={label} title={label} disabled={disabled} onClick={onClick}>{children}</button></TooltipTrigger><TooltipContent>{label}</TooltipContent></Tooltip>;}
function Numeric({label,value,onChange,min=0,max=20000,unit='mm',step=10}:{label:string;value:number;onChange:(n:number)=>void;min?:number;max?:number;unit?:string;step?:number}){const [draft,setDraft]=useState(String(value));useEffect(()=>setDraft(String(value)),[value]);const commit=()=>{const n=Number(draft);if(!Number.isFinite(n)){setDraft(String(value));return;}onChange(Math.max(min,Math.min(max,n)));setDraft(String(value));};return <label className="numeric"><span>{label}</span><div><input aria-label={label} type="number" min={min} max={max} step={step} value={draft} onChange={e=>setDraft(e.target.value)} onBlur={commit} onKeyDown={e=>{if(e.key==='Enter')e.currentTarget.blur();}}/><small>{unit}</small></div></label>;}
function Toggle({label,checked,onChange}:{label:string;checked:boolean;onChange:(n:boolean)=>void}){return <div className="toggle-row"><span>{label}</span><Switch checked={checked} onCheckedChange={onChange} aria-label={label}/></div>;}
