function Sample({m,onClick,name,selected=false}:{m:Material;onClick:()=>void;name:string;selected?:boolean}){const [image,setImage]=useState('');useEffect(()=>setImage(swatch(m.id)),[m.id]);return <button className={'sample'+(selected?' selected':'')} draggable onDragStart={e=>{e.dataTransfer.setData('material',m.id);document.documentElement.dataset.dragMaterial=m.id;}} onDragEnd={()=>{delete document.documentElement.dataset.dragMaterial;}} onClick={onClick} title={name}><span className="sample-chip" style={{backgroundColor:m.color,backgroundImage:`url(${image})`}}>{selected&&<Check size={15}/>}</span><span>{name}</span></button>;}
